let parsed;

try {
  let raw = $json.candidates[0].content.parts[0].text;
  raw = raw.replace(/```json/g, '').replace(/```/g, '').trim();
  parsed = JSON.parse(raw);
} catch (e) {
  // Gemini bloqueó el contenido, no devolvió candidates, o el JSON vino mal formado
  parsed = { intencion: "otro", apartamento: null, descripcion: null, ubicacion: null, urgente: false };
}

return [{
  json: {
    intencion: parsed.intencion,
    apartamento: parsed.apartamento,
    descripcion: parsed.descripcion,
    ubicacion: parsed.ubicacion,
    urgente: parsed.urgente,
    historial: $('Armar Historial + Mensaje Nuevo').item.json.historial,
    mensajeNuevo: $('Armar Historial + Mensaje Nuevo').item.json.mensajeNuevo
  }
}];

const rows = $input.all();
const apto = $('Parsear JSON del Clasificador').item.json.apartamento;

if (!apto) {
  return [{ json: { text: "Claro, dime el número de tu apartamento para consultar el saldo." } }];
}

const fila = rows[0]?.json;

if (!fila || !fila.numero) {
  return [{ json: { text: `No encontré el apartamento ${apto} registrado. ¿Me confirmas el número?` } }];
}

const { numero, saldo_pendiente } = fila;
const texto = saldo_pendiente > 0
  ? `El apartamento ${numero} tiene un saldo pendiente de $${saldo_pendiente}.`
  : `El apartamento ${numero} está solvente, sin saldo pendiente.`;

return [{ json: { text: texto } }];

return [{
  json: {
    historial: $json.historial,
    mensajeNuevo: $json.mensajeNuevo,
    reglamentoContext: "Sin información del reglamento para este mensaje. No inventes datos del condominio."
  }
}];

const urgente = $('Parsear JSON del Clasificador').item.json.urgente;
const descripcion = $('Parsear JSON del Clasificador').item.json.descripcion;
const ubicacionRaw = $('Parsear JSON del Clasificador').item.json.ubicacion;

// Trata como "sin ubicación" tanto null/undefined real como el string "null"
const ubicacion = (ubicacionRaw && ubicacionRaw !== "null") ? ubicacionRaw : null;
const ubicacionTexto = ubicacion ? ` en "${ubicacion}"` : "";

const texto = urgente
  ? `Esto suena urgente. Por favor comunícate DE INMEDIATO con seguridad/portería o la administración por teléfono. Ya dejé registrado tu reporte: "${descripcion}"${ubicacionTexto}.`
  : `Tu reporte fue registrado: "${descripcion}"${ubicacionTexto}. La administración le dará seguimiento.`;

return [{ json: { text: texto } }];
